-- 文件作用说明：增加隔离的租户和平台AI配置、版本化创作约束、持久图片对话及可分阶段恢复的模板任务。
CREATE TABLE assistant_tenant_ai_settings(tenant_id uuid PRIMARY KEY REFERENCES tenants(id), config jsonb NOT NULL DEFAULT '{}', secret_ciphertext text NOT NULL DEFAULT '', image_secret_ciphertext text NOT NULL DEFAULT '', version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assistant_platform_ai_settings(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), config jsonb NOT NULL DEFAULT '{}', secret_ciphertext text NOT NULL DEFAULT '', image_secret_ciphertext text NOT NULL DEFAULT '', version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assistant_contract_versions(version bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, prompt text NOT NULL, scripts jsonb NOT NULL, created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE assistant_threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), created_by uuid NOT NULL, title text NOT NULL, source text NOT NULL DEFAULT 'tenant' CHECK(source IN('tenant','platform')), template_id uuid, page_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,created_by) REFERENCES tenant_memberships(tenant_id,id), FOREIGN KEY(tenant_id,template_id) REFERENCES tenant_templates(tenant_id,id) ON DELETE SET NULL (template_id), FOREIGN KEY(tenant_id,page_id) REFERENCES decoration_pages(tenant_id,id) ON DELETE SET NULL (page_id));
CREATE TABLE assistant_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), created_by uuid NOT NULL, content_type text NOT NULL, content bytea NOT NULL, width integer NOT NULL, height integer NOT NULL, original_size integer NOT NULL, sha256 text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,created_by) REFERENCES tenant_memberships(tenant_id,id));
CREATE TABLE assistant_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), thread_id uuid NOT NULL, role text NOT NULL CHECK(role IN('user','assistant')), content text NOT NULL, asset_ids uuid[] NOT NULL DEFAULT '{}', client_message_id uuid, job_id uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), UNIQUE(tenant_id,thread_id,client_message_id), FOREIGN KEY(tenant_id,thread_id) REFERENCES assistant_threads(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE assistant_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), thread_id uuid NOT NULL, message_id uuid NOT NULL, created_by uuid NOT NULL, source text NOT NULL CHECK(source IN('tenant','platform')), config_version bigint NOT NULL, contract_version bigint NOT NULL DEFAULT 0, base_template_id uuid, base_version bigint NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','validating','succeeded','failed','cancelled')), phase text NOT NULL DEFAULT 'source' CHECK(phase IN('source','images','package')), source_result jsonb, design jsonb, applied boolean NOT NULL DEFAULT false, usage jsonb NOT NULL DEFAULT '{}', billing_status text NOT NULL DEFAULT 'not_called' CHECK(billing_status IN('not_called','reported','uncertain')), error_code text NOT NULL DEFAULT '', error_message text NOT NULL DEFAULT '', lease_until timestamptz, started_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,thread_id) REFERENCES assistant_threads(tenant_id,id) ON DELETE CASCADE, FOREIGN KEY(tenant_id,message_id) REFERENCES assistant_messages(tenant_id,id), FOREIGN KEY(tenant_id,created_by) REFERENCES tenant_memberships(tenant_id,id), FOREIGN KEY(tenant_id,base_template_id) REFERENCES tenant_templates(tenant_id,id) ON DELETE SET NULL (base_template_id));
ALTER TABLE assistant_messages ADD CONSTRAINT assistant_message_job_scope FOREIGN KEY(tenant_id,job_id) REFERENCES assistant_jobs(tenant_id,id);
CREATE UNIQUE INDEX assistant_thread_one_active_job ON assistant_jobs(tenant_id,thread_id) WHERE status IN('queued','running','validating');
CREATE INDEX assistant_job_tenant_created ON assistant_jobs(tenant_id,created_at);
ALTER TABLE assistant_jobs ADD COLUMN base_design jsonb;
COMMENT ON COLUMN assistant_jobs.base_design IS '任务创建时固定的基础设计快照，不使用调用期间变化的草稿';
CREATE TABLE assistant_image_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), job_id uuid NOT NULL, task_key text NOT NULL, path text NOT NULL, prompt text NOT NULL, width integer NOT NULL, height integer NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','running','succeeded','failed')), content bytea, content_type text NOT NULL DEFAULT '', usage jsonb NOT NULL DEFAULT '{}', billing_status text NOT NULL DEFAULT 'not_called' CHECK(billing_status IN('not_called','reported','uncertain')), error_message text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,job_id,task_key), UNIQUE(tenant_id,job_id,path), FOREIGN KEY(tenant_id,job_id) REFERENCES assistant_jobs(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE assistant_queue(job_id uuid PRIMARY KEY, tenant_id uuid NOT NULL, available_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,job_id) REFERENCES assistant_jobs(tenant_id,id) ON DELETE CASCADE);
COMMENT ON TABLE assistant_tenant_ai_settings IS '每个租户独立的模型配置与加密密钥';
COMMENT ON TABLE assistant_platform_ai_settings IS '平台自身的模型配置，不供租户冒用';
COMMENT ON TABLE assistant_contract_versions IS '平台提示词及受保护核心脚本的不可变版本';
COMMENT ON TABLE assistant_threads IS '仅用于访客模板创作的租户私有持久对话';
COMMENT ON TABLE assistant_assets IS '经检测压缩并去除元数据的对话参考图片';
COMMENT ON TABLE assistant_messages IS '模板创作对话消息，不包含访客真实聊天记录';
COMMENT ON TABLE assistant_jobs IS '分文本生成、图片生成与静态打包阶段的持久任务';
COMMENT ON TABLE assistant_image_tasks IS '逐张保存的图片生成结果，成功项不重复调用';
COMMENT ON TABLE assistant_queue IS '仅含随机编号的无业务载荷任务调度目录';
DO $$ DECLARE t text; c text; label text; BEGIN
 FOREACH t IN ARRAY ARRAY['assistant_tenant_ai_settings','assistant_platform_ai_settings','assistant_contract_versions','assistant_threads','assistant_assets','assistant_messages','assistant_jobs','assistant_image_tasks','assistant_queue'] LOOP
  FOR c IN SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=t LOOP
   label:=CASE c WHEN 'tenant_id' THEN '经认证确定的所属租户编号' WHEN 'id' THEN '随机资源编号' WHEN 'config' THEN '不含密钥的模型地址与模型名称配置' WHEN 'secret_ciphertext' THEN '绑定配置归属的加密文本模型密钥' WHEN 'image_secret_ciphertext' THEN '绑定配置归属的加密图片模型密钥' WHEN 'singleton' THEN '固定为真的平台单例标识' WHEN 'version' THEN '不可变版本或配置乐观版本编号' WHEN 'prompt' THEN '设计需求或平台创作系统提示词' WHEN 'scripts' THEN '该版本固定的SDK及聊天界面核心脚本' WHEN 'created_by' THEN '创建账号或租户成员编号' WHEN 'title' THEN '创作对话标题' WHEN 'source' THEN '使用租户自身或平台自身的AI配置' WHEN 'template_id' THEN '当前对话关联的私有模板，删除后解除关联' WHEN 'page_id' THEN '生成结果的独立装修草稿页面' WHEN 'thread_id' THEN '所属模板创作对话编号' WHEN 'role' THEN '用户或助手消息角色' WHEN 'content' THEN '消息文本或已规范化图片实际字节' WHEN 'content_type' THEN '依据实际解码确定的媒体类型' WHEN 'width' THEN '图片像素宽度' WHEN 'height' THEN '图片像素高度' WHEN 'original_size' THEN '压缩前上传图片字节数' WHEN 'sha256' THEN '规范化图片的SHA256摘要' WHEN 'asset_ids' THEN '本租户经过验证的参考图片编号数组' WHEN 'client_message_id' THEN '客户端消息幂等随机编号' WHEN 'job_id' THEN '所属或触发的持久生成任务编号' WHEN 'message_id' THEN '触发任务的用户消息编号' WHEN 'config_version' THEN '任务提交时固定的模型配置版本' WHEN 'contract_version' THEN '任务使用的平台提示词和核心脚本版本' WHEN 'base_template_id' THEN '二次创作所依据的私有模板编号' WHEN 'base_version' THEN '二次创作所依据的模板乐观版本' WHEN 'status' THEN '任务或图片当前处理状态' WHEN 'phase' THEN '文本生成、图片生成或静态文件打包阶段' WHEN 'source_result' THEN '已校验并持久保存的模型文件清单及图片任务' WHEN 'design' THEN '最终静态包设计引用，可用于保留并发候选' WHEN 'applied' THEN '是否成功应用到目标模板草稿' WHEN 'usage' THEN '仅保留白名单数值的供应商实际用量' WHEN 'billing_status' THEN '未调用、供应商报告或用量待核对状态' WHEN 'error_code' THEN '可公开显示的稳定错误分类' WHEN 'error_message' THEN '经过脱敏的失败原因' WHEN 'lease_until' THEN '工作器租约到期时间' WHEN 'task_key' THEN '图片任务在本次模型输出中的唯一编号' WHEN 'path' THEN '图片在静态包中的规范相对路径' WHEN 'available_at' THEN '下次允许调度的时间' WHEN 'started_at' THEN '任务开始时间' WHEN 'completed_at' THEN '任务终止时间' WHEN 'created_at' THEN '资源创建时间' WHEN 'updated_at' THEN '资源最近更新时间' ELSE '模板助手业务字段' END;
   EXECUTE format('COMMENT ON COLUMN %I.%I IS %L',t,c,label);
  END LOOP;
 END LOOP;
 FOREACH t IN ARRAY ARRAY['assistant_tenant_ai_settings','assistant_threads','assistant_assets','assistant_messages','assistant_jobs','assistant_image_tasks'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=current_tenant_id()) WITH CHECK(tenant_id=current_tenant_id())',t);
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='goodchat_saas_app') THEN
  GRANT SELECT,INSERT,UPDATE,DELETE ON assistant_tenant_ai_settings,assistant_platform_ai_settings,assistant_contract_versions,assistant_threads,assistant_assets,assistant_messages,assistant_jobs,assistant_image_tasks,assistant_queue TO goodchat_saas_app;
  GRANT USAGE,SELECT ON SEQUENCE assistant_contract_versions_version_seq TO goodchat_saas_app;
 END IF;
END $$;
CREATE TRIGGER immutable_assistant_contract BEFORE UPDATE OR DELETE ON assistant_contract_versions FOR EACH ROW EXECUTE FUNCTION decoration_immutable();
